const ACCOUNTS=[['cash','Cash','⌑'],['tng','TNG eWallet','◉'],['shopeepay','ShopeePay','S'],['maybank','Maybank','M'],['wise','Wise','W']];
const EXPENSES=['Food & drinks','Fuel & transport','Mobile & internet','Bills & subscriptions','Family & giving','Social & lifestyle','Shopping','Healthcare','Education','Other'];
const INCOMES=['Salary','Foodpanda','Other income','Refund / reimbursement','Gift received'];
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
let state=JSON.parse(localStorage.getItem('my-money-v1')||'{"transactions":[],"settings":{"scriptUrl":""}}');
state.settings=state.settings||{};
const fmt=n=>new Intl.NumberFormat('en-MY',{style:'currency',currency:'MYR',minimumFractionDigits:2}).format(n||0).replace('MYR','RM');
const save=()=>localStorage.setItem('my-money-v1',JSON.stringify(state));
const todayParts=()=>{const d=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`};
const today=todayParts;const thisMonth=d=>d.slice(0,7)===today().slice(0,7);
function transactionAmount(t,a){if(t.type==='income'){a[t.account]+=t.amount;return}if(t.type==='expense'){a[t.account]-=t.amount;return}a[t.account]-=t.amount;a[t.destination]+=t.amount}
function balances(){const a=Object.fromEntries(ACCOUNTS.map(x=>[x[0],0]));state.transactions.forEach(t=>transactionAmount(t,a));return a}
function allSelects(){const accountOptions=ACCOUNTS.map(([id,n])=>`<option value="${id}">${n}</option>`).join('');$('#account').innerHTML=accountOptions;$('#destination').innerHTML=accountOptions;}
function iconFor(t){return t.type==='income'?'↓':t.type==='expense'?'↑':'⇄'}
function row(t){const amount=t.type==='expense'?`−${fmt(t.amount)}`:t.type==='income'?`+${fmt(t.amount)}`:`${fmt(t.amount)}`;const label=t.type==='transfer'?`${name(t.account)} → ${name(t.destination)}`:t.category;return `<div class="transaction-row"><div class="transaction-icon">${iconFor(t)}</div><div><b>${label}</b><small>${t.note||t.date}</small></div><strong class="${t.type==='expense'?'out':t.type==='income'?'in':''}">${amount}</strong></div>`}
function name(id){return ACCOUNTS.find(a=>a[0]===id)?.[1]||id}
const notStart=t=>t.category!=='Starting balance';
function render(){const month=state.transactions.filter(t=>thisMonth(t.date)&&notStart(t));const income=month.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0);const spent=month.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);const saved=income-spent;const a=balances();$('#month-label').textContent=new Intl.DateTimeFormat('en-MY',{month:'long',year:'numeric'}).format(new Date()).toUpperCase();$('#total-balance').textContent=fmt(Object.values(a).reduce((s,n)=>s+n,0));$('#month-income').textContent=`↓ ${fmt(income)} in`;$('#month-expense').textContent=`↑ ${fmt(spent)} out`;$('#saved-amount').textContent=fmt(saved);$('#spent-amount').textContent=fmt(spent);$('#saved-rate').textContent=income?`${Math.round(saved/income*100)}% of income kept`:'Add your first entry';$('#spent-count').textContent=`${month.filter(t=>t.type==='expense').length} transaction${month.filter(t=>t.type==='expense').length===1?'':'s'}`;
$('#accounts-list').innerHTML=ACCOUNTS.map(([id,n,i])=>`<div class="account-row"><div class="account-icon">${i}</div><div><b>${n}</b><small>Current balance</small></div><strong>${fmt(a[id])}</strong></div>`).join('');const latest=[...state.transactions].sort((x,y)=>y.date.localeCompare(x.date)).slice(0,5);const empty='<p class="empty-state">No entries yet — start with Money in or Spend.</p>';$('#recent-list').innerHTML=latest.length?latest.map(row).join(''):empty;$('#history-list').innerHTML=state.transactions.length?[...state.transactions].sort((x,y)=>y.date.localeCompare(x.date)).map(row).join(''):empty;
const cats={};month.filter(t=>t.type==='expense').forEach(t=>cats[t.category]=(cats[t.category]||0)+t.amount);const max=Math.max(...Object.values(cats),1);$('#category-chart').innerHTML=Object.keys(cats).length?Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div class="category-row"><span>${c}</span><div class="bar"><i style="width:${v/max*100}%"></i></div><b>${fmt(v)}</b></div>`).join(''):'<p class="empty-state">Your spending pattern will appear here.</p>';
const year=today().slice(0,4),yr=state.transactions.filter(t=>t.date.startsWith(year)&&notStart(t));const yi=yr.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),ye=yr.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);$('#annual-summary').innerHTML=`<div><span>Income</span><b>${fmt(yi)}</b></div><div><span>Spent</span><b>${fmt(ye)}</b></div><div><span>Saved</span><b>${fmt(yi-ye)}</b></div>`;$('#annual-year').textContent=year;const months=Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0'));const vals=months.map(m=>yr.filter(t=>t.type==='expense'&&t.date.slice(5,7)===m).reduce((s,t)=>s+t.amount,0)),high=Math.max(...vals,1);$('#year-bars').innerHTML=vals.map((v,i)=>`<div class="year-bar"><i style="height:${Math.max(2,v/high*112)}px"></i>${['J','F','M','A','M','J','J','A','S','O','N','D'][i]}</div>`).join('');const sources={};state.transactions.filter(t=>t.type==='income'&&notStart(t)).forEach(t=>sources[t.category]=(sources[t.category]||0)+t.amount);const imax=Math.max(...Object.values(sources),1);$('#income-chart').innerHTML=Object.keys(sources).length?Object.entries(sources).map(([c,v])=>`<div class="category-row"><span>${c}</span><div class="bar"><i style="width:${v/imax*100}%"></i></div><b>${fmt(v)}</b></div>`).join(''):'<p class="empty-state">Income sources will appear after your first entry.</p>';}
function openEntry(type){$('#entry-type').value=type;$('#entry-kicker').textContent=type==='income'?'MONEY IN':type==='expense'?'MONEY OUT':'TRANSFER';$('#entry-title').textContent=type==='income'?'Add income':type==='expense'?'Add spending':'Move money';$('#account-label').textContent=type==='income'?'Received in':type==='expense'?'Paid from':'From';$('#category-label').textContent=type==='income'?'Source':'Category';$('#note-label').innerHTML='Note <em>optional</em>';$('#note').placeholder=type==='income'?'e.g. March salary':type==='expense'?'e.g. ZUS Coffee':'e.g. Top up TNG';$('#destination-wrap').hidden=type!=='transfer';$('#category-wrap').hidden=type==='transfer';$('#category').innerHTML=(type==='income'?INCOMES:EXPENSES).map(x=>`<option>${x}</option>`).join('');$('#date').value=today();$('#amount').value='';$('#note').value='';$('#entry-dialog').showModal();setTimeout(()=>$('#amount').focus(),50)}
$('#entry-form').addEventListener('submit',e=>{e.preventDefault();const type=$('#entry-type').value,amount=Number($('#amount').value),account=$('#account').value,destination=$('#destination').value;if(type==='transfer'&&account===destination)return toast('Choose a different destination account.');if(!amount||amount<=0)return;state.transactions.push({id:crypto.randomUUID(),type,amount,account,destination:type==='transfer'?destination:'',category:type==='transfer'?'Transfer':$('#category').value,note:$('#note').value.trim(),date:$('#date').value,createdAt:Date.now(),synced:false});save();$('#entry-dialog').close();render();toast('Entry saved on this device.');});
$$('.action').forEach(b=>b.addEventListener('click',()=>openEntry(b.dataset.type)));$$('.nav-item').forEach(b=>b.addEventListener('click',()=>{$$('.nav-item').forEach(x=>x.classList.toggle('active',x===b));$$('.page').forEach(x=>x.classList.toggle('active',x.id===b.dataset.page));window.scrollTo({top:0,behavior:'smooth'})}));
$$('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.closeDialog).close()));
function openBalances(){$('#balance-fields').innerHTML=ACCOUNTS.map(([id,n])=>{const ex=state.transactions.find(t=>t.category==='Starting balance'&&t.account===id);return `<label><span>${n}</span><input data-balance-account="${id}" type="number" inputmode="decimal" min="0" step="0.01" placeholder="0.00" value="${ex?ex.amount:''}" /></label>`}).join('');$('#balance-dialog').showModal()}
$('#balance-button').onclick=openBalances;
$('#balance-form').addEventListener('submit',e=>{e.preventDefault();$$('[data-balance-account]').forEach(inp=>{const id=inp.dataset.balanceAccount,amount=Number(inp.value),ex=state.transactions.find(t=>!notStart(t)&&t.account===id);if(ex?ex.amount===amount:amount<=0)return;state.transactions=state.transactions.filter(t=>t!==ex);state.transactions.push({id:crypto.randomUUID(),type:'income',amount,account:id,destination:'',category:'Starting balance',note:'Starting balance',date:today(),createdAt:Date.now(),synced:false});});state.onboarded=true;save();$('#balance-dialog').close();render();toast('Starting balances saved.');});
$('#settings-button').onclick=()=>{$('#script-url').value=state.settings.scriptUrl||'';$('#settings-dialog').showModal()};$('#settings-form').addEventListener('submit',e=>{e.preventDefault();state.settings.scriptUrl=$('#script-url').value.trim();save();$('#settings-dialog').close();toast('Settings saved.');pull();});
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}
async function doSync(list){const url=$('#script-url').value.trim();if(!url)return toast('Add your Apps Script URL first.');if(!list.length)return toast('Everything is already synced.');try{await fetch(url,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:'appendTransactions',transactions:list})});list.forEach(t=>t.synced=true);save();toast(`${list.length} entries sent to Google Sheets.`)}catch{toast('Could not reach the sync bridge.');}}
// Only the newest starting balance per account counts; older ones in the Sheet are superseded edits.
function keepLatestStart(){const latest={};state.transactions.filter(t=>!notStart(t)).forEach(t=>{if(!latest[t.account]||t.createdAt>latest[t.account].createdAt)latest[t.account]=t});state.transactions=state.transactions.filter(t=>notStart(t)||latest[t.account]===t)}
async function pull(){const url=state.settings.scriptUrl;if(!url)return;try{const {transactions}=await(await fetch(url)).json();const before=state.transactions.length,known=new Set(state.transactions.map(t=>t.id));state.transactions.push(...transactions.filter(t=>!known.has(t.id)).map(t=>({...t,synced:true})));keepLatestStart();if(state.transactions.some(t=>!notStart(t)))state.onboarded=true;save();render();const added=state.transactions.length-before;if(added>0)toast(`${added} entries loaded from Google Sheets.`)}catch{toast('Could not load from Google Sheets.')}}
$('#sync-button').onclick=async()=>{await doSync(state.transactions.filter(t=>!t.synced));pull()};
$('#resync-button').onclick=()=>{if(confirm('Resend every entry to the Sheet? Already-synced rows will not be duplicated there.'))doSync(state.transactions);};
$('#clear-button').onclick=()=>{if(confirm('Clear all locally saved transactions? Your Google Sheet is not changed.')){state.transactions=[];save();$('#settings-dialog').close();render();toast('Local data cleared.')}};$('#history-button').onclick=()=>document.querySelector('[data-page="history-page"]').click();$('#export-button').onclick=()=>{const rows=[['Date','Type','Account','Destination','Category','Amount','Note'],...state.transactions.map(t=>[t.date,t.type,name(t.account),t.destination?name(t.destination):'',t.category,t.amount,t.note])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\n')],{type:'text/csv'}));a.download='my-money-transactions.csv';a.click()};
allSelects();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');if(!state.onboarded)openBalances();pull();
